custom_css:
/* 原：7702 灵感来源：QQ | 二改：苦咖啡  自动日夜间切换版 */

:root {

    --st-main-text: rgba(74, 74, 74, 1);
    --st-italics: rgba(188, 188, 188, 1);
    --bar-bg-color: #FFFFFF;
    --bar-border-color: #E0E0E0;
    --bar-icon-color: #555555;
    --bar-text-color: #333333;
    --avatar-bg-img: url('https://i.postimg.cc/N0nxHshz/galc0o.png');

    --slider-track-bg: #cccccc;
    --slider-thumb-border: #E7E7E7;
    --slider-thumb-bg: #ffffff;
    --checkbox-bg: #e0e0e0;
    --checkbox-thumb: #ffffff;
    --checkbox-checked-bg: #555555;
    --drawer-bg: #E7E7E7;
    --drawer-border: rgba(0,0,0,0.05);
    --input-bg: #FFFFFF;
    --input-border: #dcdcdc;
    --pm-header-color: #555555;
    --pm-separator: rgba(0, 0, 0, 0.08);
    --pm-selected-bg: #dcdcdc;
    --pm-drag-handle: #aaaaaa;
    --avatar-selected-text: #333333;
    --scrollbar-thumb-light: rgba(0, 0, 0, 0.15);
    --scrollbar-thumb-heavy: rgba(0, 0, 0, 0.2);
    --mes-wrapper-bg: #ffffff;
    --mes-wrapper-border: #cccccc;
    --mes-arrow-color: #bbbbbb;
    --mes-block-bg: #ffffff;
    --mes-shadow: rgba(0, 0, 0, 0.1);
    --mes-name-bg: rgba(0, 0, 0, 0.03);
    --mes-name-border: #f0f0f0;
    --mes-timestamp-color: #888;
    --reasoning-bg: #FFFFFF;
    --reasoning-border: #E0E0E0;
    --reasoning-hover: #f5f5f5;
    --code-bg: #f7f7f9;
    --code-text: #333333;
    --code-inline-text: #5A5A5A;
    --quote-bg: #f0f0f0;
    --quote-text: #777777;
    --edit-text-bg: rgba(190, 190, 195, 0.3);
    --edit-text-color: #333;
    --btn-regular-text: #888;
    --btn-fav-bg: rgba(255, 193, 7, 0.1);
    --btn-green-bg: rgba(76, 175, 80, 0.1);
    --btn-red-bg: rgba(220, 53, 69, 0.1);
}

@media (prefers-color-scheme: dark) {
    :root {

        --st-main-text: rgba(220, 220, 220, 1);
        --st-italics: rgba(120, 120, 120, 1);
        --bar-bg-color: #252527;
        --bar-border-color: #3a3a3c;
        --bar-icon-color: #b0b0b0;
        --bar-text-color: #dcdcdc;

        --avatar-bg-img: url('https://i.postimg.cc/Gmg9fV74/dipspr.png');

        --slider-track-bg: #444444;
        --slider-thumb-border: #1c1c1e;
        --slider-thumb-bg: #dcdcdc;
        --checkbox-bg: #444444;
        --checkbox-thumb: #1c1c1e;
        --checkbox-checked-bg: #777777;
        --drawer-bg: #1c1c1e;
        --drawer-border: rgba(255,255,255,0.08);
        --input-bg: #2c2c2e;
        --input-border: #444444;
        --pm-header-color: #bbbbbb;
        --pm-separator: rgba(255,255,255,0.08);
        --pm-selected-bg: #3a3a3c;
        --pm-drag-handle: #666666;
        --avatar-selected-text: #ffffff;
        --scrollbar-thumb-light: rgba(255,255,255,0.15);
        --scrollbar-thumb-heavy: rgba(255,255,255,0.2);
        --mes-wrapper-bg: #2c2c2e;
        --mes-wrapper-border: #444444;
        --mes-arrow-color: #777777;
        --mes-block-bg: #2c2c2e;
        --mes-shadow: rgba(0, 0, 0, 0.2);
        --mes-name-bg: rgba(255,255,255,0.05);
        --mes-name-border: #3a3a3c;
        --mes-timestamp-color: #777777;
        --reasoning-bg: #3a3a3c;
        --reasoning-border: #555555;
        --reasoning-hover: #4a4a4c;
        --code-bg: #1e1e1e;
        --code-text: #cccccc;
        --code-inline-text: #bbbbbb;
        --quote-bg: rgba(255,255,255,0.1);
        --quote-text: #999999;
        --edit-text-bg: rgba(0,0,0,0.3);
        --edit-text-color: #ffffff;
        --btn-regular-text: #999999;
        --btn-fav-bg: rgba(255, 193, 7, 0.2);
        --btn-green-bg: rgba(76, 175, 80, 0.2);
        --btn-red-bg: rgba(220, 53, 69, 0.2);
    }
}


body, #chat, .mes_text { color: var(--st-main-text) !important; }
i, em, u, blockquote { color: var(--st-italics) !important; }

#dialogue_del_mes {
    z-index: 9999 !important;
}

#dialogue_del_mes_ok,
#dialogue_del_mes_cancel {
    pointer-events: auto !important;
    position: relative; 
    z-index: 10000 !important;
}

#chat {
    padding-top: 80px !important;
    padding-bottom: 150px !important;
}

#top-bar-bg,
#form_sheld {
    position: absolute !important;
    left: 0; right: 0; width: 100% !important;
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
    z-index: 100;
    display: flex;
    justify-content: center;
    pointer-events: none;
}

#top-bar-bg {
    top: 0 !important;
    padding-top: 15px !important;
}
#form_sheld {
    bottom: 0 !important;
    padding-bottom: 0 !important;
}

#top-settings-holder {
    background-color: var(--bar-bg-color) !important;
    border: 1px solid var(--bar-border-color) !important; 
    box-shadow: none !important;
    border-radius: 0 0 8px 8px !important; 
    backdrop-filter: none !important;
    max-width: 800px !important;
    width: 100%;
    display: flex;
    justify-content: center;
    gap: 1px;
    align-items: center;
    padding: 8px 8px !important;
    pointer-events: auto;
}

#top-settings-holder .drawer-toggle.drawer-header {
    background-color: transparent !important;
    border: none !important;
    box-shadow: none !important;
    border-radius: 0 !important;
    padding: 0 !important;
    margin: 0 !important;
    width: auto;
}

#form_sheld #send_form {
    background: var(--bar-bg-color) !important;
    border: 1px solid var(--bar-border-color) !important;
    box-shadow: none !important;
    border-radius: 12px !important; 
    backdrop-filter: none !important;
    max-width: 800px !important;
    width: 100%;
    pointer-events: auto;
    padding: 4px 5px !important;
}

#top-settings-holder .menu_button,
#top-settings-holder .title,
#send_textarea,
#send_textarea::placeholder,
#leftSendForm .interactable,
#rightSendForm .interactable {
    color: var(--bar-text-color) !important;
}

#top-settings-holder .drawer-toggle .drawer-icon,
#top-settings-holder .drawer-toggle:hover .drawer-icon,
#top-settings-holder .drawer-toggle:active .drawer-icon,
#top-settings-holder .drawer-toggle .drawer-icon.closedIcon,
#top-settings-holder .drawer-toggle .drawer-icon.openedIcon {
    color: var(--bar-icon-color) !important;
    text-shadow: none !important;
}

#send_textarea {
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
}
#send_textarea::placeholder {
    opacity: 0.7;
}

#top-bar {
    display: none !important;
}

#qr--bar .menu_button {
    background: none !important;
    border: none !important;
    box-shadow: none !important;
}

#qr--bar .qr--button .qr--button-label {
    color: var(--btn-regular-text) !important;
    font-weight: 500;
}

*, *::before, *::after {
    box-shadow: none !important;  
    text-shadow: none !important; 
    filter: none !important;     
    outline: none !important;  
}
.drawer-content, .popup, .inline-drawer, #sheld, #chat, #top-bar {
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
}

input[type="range"] {
    -webkit-appearance: none;
    appearance: none;
    width: 100%;
    height: 24px; 
    background: transparent !important;
    padding: 0;
    margin: 0;
    border: none !important;
}
input[type="range"]::-webkit-slider-runnable-track {
    width: 100%;
    height: 6px; 
    cursor: pointer;
    background: var(--slider-track-bg) !important; 
    border-radius: 10px;
    border: none !important;
}
input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none;
    height: 16px; 
    width: 16px;
    border-radius: 50%;
    background: var(--slider-thumb-bg) !important;
    border: 2px solid var(--slider-thumb-border) !important; 
    cursor: pointer;
    margin-top: -5px; 
}
input[type="range"]::-moz-range-track {
    width: 100%;
    height: 6px;
    cursor: pointer;
    background: var(--slider-track-bg) !important;
    border-radius: 10px;
    border: none !important;
}
input[type="range"]::-moz-range-thumb {
    height: 16px;
    width: 16px;
    border: 2px solid var(--slider-thumb-border) !important;
    border-radius: 50%;
    background: var(--slider-thumb-bg) !important;
    cursor: pointer;
}

input[type="checkbox"] {
    -webkit-appearance: none;
    appearance: none;
    width: 28px; 
    height: 16px;
    border-radius: 8px;
    background-color: var(--checkbox-bg) !important;
    position: relative;
    vertical-align: middle;
    cursor: pointer;
    border: none !important;
    margin-right: 8px;
    margin-top: -2px;
}
input[type="checkbox"]::before {
    content: '';
    position: absolute;
    width: 12px;
    height: 12px;
    border-radius: 50%;
    background-color: var(--checkbox-thumb) !important;
    top: 2px;
    left: 2px; 
}
input[type="checkbox"]:checked {
    background-color: var(--checkbox-checked-bg) !important;
}
input[type="checkbox"]:checked::before {
    left: 14px;
}

body .drawer-content h3,
body .drawer-content h4,
body .drawer-content .standoutHeader,
body .drawer-content .inline-drawer-toggle {
    background: var(--drawer-bg) !important;
    border: none !important;
    border-radius: 12px !important; 
    padding: 12px 14px;
    margin-top: 12px;
    margin-bottom: 8px;
    color: var(--bar-text-color) !important; 
}
body .drawer-content .inline-drawer:not(.closed) .inline-drawer-toggle {
    border-bottom-left-radius: 0 !important;
    border-bottom-right-radius: 0 !important;
}
body .drawer-content .inline-drawer-content {
    background: var(--drawer-bg) !important;
    border: none !important;
    border-top: 1px solid var(--drawer-border) !important;
    border-radius: 0 0 12px 12px !important;
    padding: 14px;
    margin-top: -8px;
    margin-bottom: 10px;
    color: var(--bar-text-color) !important;
}
#WorldInfo .inline-drawer-content {
    background-color: var(--drawer-bg) !important;
}

.text_pole,
textarea,
select,
input[type="text"],
input[type="number"],
input[type="search"],
input[type="password"] {
    background: var(--input-bg) !important;
    border: 1px solid var(--input-border) !important;
    border-radius: 8px !important; 
    padding: 8px 10px !important;
    color: var(--bar-text-color) !important;
}
.text_pole:focus,
textarea:focus,
select:focus,
input[type="text"]:focus,
input[type="number"]:focus,
input[type="password"]:focus {
    border-color: var(--input-border) !important;
}
.select2-selection__choice__display {
    color: var(--bar-text-color) !important;
}
.inline-drawer-toggle.inline-drawer-icon,
.inline-drawer-toggle.inline-drawer-icon:hover {
    background: transparent !important;
    border: none !important;
    padding: 0 !important;
    margin-top: 2px !important;
    width: 24px;
    height: 24px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    color: var(--bar-icon-color) !important;
}

.completion_prompt_manager_header {
    background: transparent !important;
    padding: 10px 15px !important;
    border-bottom: 1px solid var(--pm-separator) !important; 
    display: flex;
    justify-content: space-between;
    align-items: center;
    border-radius: 0 !important;
    margin-bottom: 0 !important;
}
.completion_prompt_manager_header > span,
.completion_prompt_manager_header div {
    color: var(--pm-header-color) !important;
    font-weight: 600 !important;
    font-size: 0.9em !important;
}
#completion_prompt_manager_list {
    background: transparent !important;
    border: none !important;
    padding: 0;
    padding-right: 30px !important;
    box-sizing: border-box !important;
    list-style: none;
    margin-top: 10px;
}
#completion_prompt_manager_list .completion_prompt_manager_list_head {
    padding: 8px 15px;
    font-size: 0.85em;
    font-weight: 600;
    color: var(--btn-regular-text) !important;
}
#completion_prompt_manager_list .completion_prompt_manager_list_separator hr {
    border: none;
    border-top: 1px solid var(--pm-separator) !important;
    margin: 8px 0;
}
.completion_prompt_manager_prompt {
    background-color: transparent !important; 
    border: 1px solid transparent !important;
    display: flex;
    align-items: center;
    padding: 10px 15px;
    border-radius: 10px;
    margin: 4px 8px;
}
.completion_prompt_manager_prompt:hover {
    background-color: transparent !important;
    border-color: transparent !important; 
}
.completion_prompt_manager_prompt.selected,
.completion_prompt_manager_prompt.active {
    background-color: var(--pm-selected-bg) !important;
}
.completion_prompt_manager_prompt .completion_prompt_manager_prompt_name a {
    color: var(--bar-text-color) !important;
}
.completion_prompt_manager_prompt.selected .completion_prompt_manager_prompt_name a,
.completion_prompt_manager_prompt.active .completion_prompt_manager_prompt_name a {
    font-weight: 600;
}
.completion_prompt_manager_prompt .drag-handle { color: var(--pm-drag-handle) !important; }
.completion_prompt_manager_prompt .completion_prompt_manager_prompt_name .fa-fw { color: var(--btn-regular-text) !important; }
.prompt-manager-toggle-action.fa-toggle-on { color: var(--bar-icon-color) !important; }
.prompt-manager-toggle-action.fa-toggle-off { color: var(--pm-drag-handle) !important; }
.completion_prompt_manager_prompt .prompt_manager_prompt_controls .fa-solid:hover { 
    color: inherit !important;
}

.drawer-content .select2-container--default .select2-selection--multiple,
.drawer-content .select2-selection {
    background-color: transparent !important;
    border: none !important;
}
.drawer-content .select2-selection__choice {
    background-color: var(--bar-bg-color) !important; 
    border: 1px solid var(--bar-border-color) !important;
    color: var(--bar-text-color) !important;
    border-radius: 2px !important;
    margin-top: 6px !important;
    padding: 0 !important;
    display: inline-flex !important;
    align-items: center !important;
}
.drawer-content .select2-selection__choice__display {
    background-color: transparent !important;
    color: var(--bar-text-color) !important;
    padding: 2px 8px !important;
    cursor: default !important;
    font-size: 0.9em;
}
.drawer-content .select2-selection__choice__remove {
    background-color: transparent !important;
    border: none !important;
    color: #888 !important; 
    margin: 0 !important;
    padding: 0 5px 0 0 !important;
    opacity: 1 !important;
    border-right: 1px solid var(--bar-border-color) !important; 
}
.drawer-content .select2-search__field {
    margin-top: 7px !important;
    color: var(--bar-text-color) !important;
    background: transparent !important;
}
.drawer-content .select2-selection__clear {
    color: #999 !important;
    background: transparent !important;
}

.drawer-content #user_avatar_block .avatar-container {
    background-color: transparent !important;
    border: 1px solid transparent !important;
    border-radius: 12px !important;
    padding: 8px !important;
    margin-bottom: 8px !important;
}
.drawer-content #user_avatar_block .avatar-container.selected {
    background-color: var(--pm-selected-bg) !important; 
}
.drawer-content #user_avatar_block .avatar-container.selected .ch_name {
    color: var(--avatar-selected-text) !important;
    font-weight: 700 !important;
}

.drawer-content #HotSwapWrapper {
    width: 100% !important;
    overflow: hidden !important;
    padding: 0 5px !important;
    box-sizing: border-box !important;
    display: block !important;
}
.drawer-content #HotSwapWrapper .hotswap.avatars_inline {
    display: flex !important;
    flex-direction: row !important;
    flex-wrap: nowrap !important;
    overflow-x: auto !important;
    overflow-y: hidden !important;
    justify-content: flex-start !important;
    align-items: center !important;
    width: 100% !important;
    max-width: 100% !important;
    padding-bottom: 8px !important; 
    scroll-behavior: smooth;
    scrollbar-width: thin !important;
    scrollbar-color: var(--scrollbar-thumb-heavy) transparent !important;
}
.drawer-content #HotSwapWrapper .avatar {
    flex-shrink: 0 !important;
    margin-right: 10px !important;
    display: inline-flex !important;
}
.drawer-content #HotSwapWrapper .hotswap.avatars_inline::-webkit-scrollbar {
    height: 6px !important; 
    display: block !important;
}
.drawer-content #HotSwapWrapper .hotswap.avatars_inline::-webkit-scrollbar-track {
    background: transparent !important; 
}
.drawer-content #HotSwapWrapper .hotswap.avatars_inline::-webkit-scrollbar-thumb {
    background: var(--scrollbar-thumb-light) !important;
    border-radius: 10px !important;
    border: 1px solid transparent !important; 
    background-clip: content-box !important;
}

#top-settings-holder .drawer-toggle .drawer-icon {
    font-size: 1.55em !important; 
    display: inline-flex;
    align-items: center;
    justify-content: center;
}
#leftSendForm .fa-solid,
#rightSendForm .fa-solid,
.mes_buttons .fa-solid {
    font-size: 18px !important;
}

.mes {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0;
    margin-bottom: 30px;
    position: relative; 
    padding: 0;
}
.mes .mesAvatarWrapper {
    width: 280px;
    height: 80px;
    background-color: var(--mes-wrapper-bg);
    border: 1px solid var(--mes-wrapper-border);
    border-radius: 16px;
    box-shadow: none;
    display: flex;
    align-items: center;
    justify-content: flex-start;
    padding-left: 10px; 
    position: relative;
    z-index: 2;
    margin-bottom: -40px; 
    flex-shrink: 0;
}
.mes .avatar {
    position: relative;
    top: -4px;
    display: inline-block;
}
.mes .avatar img {
    width: 60px;
    height: 60px;
    border-radius: 50%;
    border: none;
    box-shadow: none;
}
.mes .avatar::after {
    content: '';
    position: absolute;
    top: -20px;
    left: -20px;
    z-index: 1;
    width: 100px;
    height: 100px;
    background-image: var(--avatar-bg-img);
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    pointer-events: none;
}
.mes .mesAvatarWrapper::after {
    content: '';
    position: absolute;
    top: 50%;
    right: 20px;
    width: 6px;
    height: 6px;
    border-top: 1px solid var(--mes-arrow-color);
    border-right: 1px solid var(--mes-arrow-color);
    transform: translateY(-50%) rotate(45deg);
}
.mes.last_mes .mes_block,
.mes.last_mes .ch_name {
    position: static !important;
}
.mes .ch_name .flex-container.alignItemsBaseline {
    position: absolute !important;
    z-index: 50 !important;
    top: 40px !important;
    left: 50% !important;
    transform: translateX(-55px) translateY(-50%) !important;
}
.mes.last_mes .avatar {
    top: 20px !important;
}
.mes .mes_block {
    width: 100%;
    max-width: 720px;
    background-color: var(--mes-block-bg);
    border-radius: 12px;
    box-shadow: 0 4px 12px var(--mes-shadow);
    overflow: hidden;
    border: none;
    backdrop-filter: none;
    padding: 0;
}
.mes .ch_name {
    display: flex;
    justify-content: flex-end; 
    align-items: center;
    padding: 20px 15px 10px 15px;
    background-color: var(--mes-name-bg);
    border-bottom: 1px solid var(--mes-name-border);
    position: static;
    height: auto;
    width: auto;
}
.mes .ch_name .flex-container.alignItemsBaseline {
    position: absolute;
    z-index: 3;
    top: 32px;
    left: 50%;
    transform: translateX(-55px) translateY(-50%);
}
.mes .name_text {
    font-size: 1.2em;
    font-weight: bold;
}
.mes .timestamp {
    font-size: 0.8em;
    color: var(--mes-timestamp-color);
    margin-left: 12px;
}
.mes .mes_ghost { display: none; }
.mes .mes_buttons {
    position: relative;
    z-index: 4;
    color: var(--btn-regular-text);
}
.mes .mesIDDisplay, .mes .mes_timer, .mes .tokenCounterDisplay {
    display: block !important;
    position: absolute;
    z-index: 3;
    top: 55px;
    font-size: 0.7em;
    color: var(--mes-timestamp-color);
    background-color: transparent;
    padding: 2px 0;
}
.mes .mesIDDisplay {
    left: 50%;
    transform: translateX(-55px);
}
.mes .mes_timer {
    left: 50%;
    transform: translateX(-25px);
}
.mes .tokenCounterDisplay {
    left: 50%;
    transform: translateX(10px);
}
.mes .mesIDDisplay:empty::before,
.mes .mes_timer:empty::before,
.mes .tokenCounterDisplay:empty::before {
    content: '*';
}
.mes .mes_text {
    padding: 15px 20px;
    line-height: 1.6;
}
.mes .mes_text p:first-child { margin-top: 0; }
.mes .mes_text p:last-child { margin-bottom: 0; }
.mes[is-user="true"] .mes_block { background-color: var(--mes-block-bg); }
.mes .mes_reasoning_header {
    background-color: var(--reasoning-bg) !important;
    border: 1px solid var(--reasoning-border) !important;
    box-shadow: none !important;
    backdrop-filter: none !important;
    border-radius: 12px !important;             
    padding: 8px 15px !important;
    margin-left: 50px !important;
    margin-top: 20px !important;
    margin-bottom: 15px !important;
    width: fit-content !important; 
    transition: background-color 0.2s ease;
    cursor: pointer;
}
.mes .mes_reasoning_header:hover {
    background-color: var(--reasoning-hover) !important;
}
.mes .mes_reasoning_header .thinking-icon {
    height: 1em !important;
    width: auto !important;
    vertical-align: -0.15em !important;
    margin-right: 8px;
}
.mes {
    position: relative;
}
.mes_edit_buttons {
    position: absolute;
    top: 0;
    right: 0;
    z-index: 10;
}
.mes_edit_buttons .menu_button {
