code[data-highlighted="yes"] {
    display: block;
    position: relative;
    background: var(--code-bg) !important;
    border: 1px solid var(--border-subtle) !important;
    box-shadow: 0 2px 8px rgba(0,0,0,0.06) !important;
    border-radius: 12px;
    padding: 15px;
    padding-right: 45px;
    margin: 10px 0;
    color: var(--code-text) !important; 
    line-height: 1.6;
}
.code-copy {
    position: absolute;
    top: 15px;
    right: 15px;
    color: var(--code-text);
    cursor: pointer;
    opacity: 0.5;
    transition: all 0.2s ease;
}
code[data-highlighted="yes"]:hover .code-copy {
    opacity: 1;
    color: var(--code-text);
}
.code-copy:hover {
    transform: scale(1.1);
}
code:not([data-highlighted="yes"]) {
    display: inline-block;
    background-color: var(--code-bg) !important;
    border: 1px solid var(--border-subtle) !important;
    border-radius: 5px;
    padding: 2px 8px;
    margin: 0 2px;
    font-size: 0.9em;
    color: var(--code-inline-text) !important;
}
.mes_text q {
    text-decoration: none; 
    background-color: var(--quote-bg);
    padding: 2px 8px;
    border-radius: 6px; 
    color: var(--quote-text);
    font-style: italic;
    quotes: none;
    vertical-align: middle; 
}

#curEditTextarea {
    background-color: var(--edit-text-bg) !important; 
    border: none !important;
    box-shadow: none !important;
    border-radius: 8px !important;
    color: var(--edit-text-color) !important;
    padding: 10px !important;
    line-height: 1.6 !important;
    width: 100% !important;
    box-sizing: border-box !important;
}

#curEditTextarea:focus {
    box-shadow: none !important;
    outline: none !important;
}

*::-webkit-scrollbar {
    width: 10px;
    height: 10px;
}

*::-webkit-scrollbar-track {
    background: transparent;
}

*::-webkit-scrollbar-thumb {
    background-color: var(--scrollbar-thumb-heavy); 
    border-radius: 10px;
    border: none;
    backdrop-filter: none;
}

*::-webkit-scrollbar-thumb:hover {
    background-color: var(--scrollbar-thumb-heavy); 
}

* {
    scrollbar-width: thin; 
    scrollbar-color: var(--scrollbar-thumb-heavy) transparent;
}

@keyframes slideInFromLeft {
    from { opacity: 0; transform: translateX(-30px); }
    to { opacity: 1; transform: translateX(0); }
}
@keyframes slideInFromRight {
    from { opacity: 0; transform: translateX(30px); }
    to { opacity: 1; transform: translateX(0); }
}
.mes:not([is_user="true"]) {
    animation: slideInFromLeft 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}
.mes[is_user="true"] {
    animation: slideInFromRight 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

