}

.mes .mesIDDisplay {
    left: calc(50% - 55px) !important;
}

.mes .mes_timer {
    left: calc(50% - 25px) !important;
}

.mes .tokenCounterDisplay {
    left: calc(50% + 10px) !important;
}

